import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireGlu Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireGlu/aireglu-v1-123-0.md","filePath":"aireblock-releases/AireGlu/aireglu-v1-123-0.md","lastUpdated":1790237058000}`),a={name:`aireblock-releases/AireGlu/aireglu-v1-123-0.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireglu-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireglu-icon.png"> AireGlu Release Notes</span> <a class="header-anchor" href="#aireglu-release-notes" aria-label="Permalink to “AireGlu Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> v1.123.0<br><strong>Release Date:</strong> 23 September 2026</p></blockquote><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Array Support for Callback Endpoint Output (GLU-2917)</li><li>Test Functionality for Error Email Setup (GLU-2259)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Fixed Repository-Linked MCP Server Resolution (GLU-3275)</li><li>Fixed Body Editor Blocked When Format Is Stream (GLU-3279)</li></ul><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="array-support-for-callback-endpoint-output-glu-2917" tabindex="-1">Array Support for Callback Endpoint Output (GLU-2917) <a class="header-anchor" href="#array-support-for-callback-endpoint-output-glu-2917" aria-label="Permalink to “Array Support for Callback Endpoint Output (GLU-2917)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The Callback input type schema now accepts an array, in addition to an object, for endpointOutput, since both are valid representations of the same JSON data.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>If your callback configuration returns endpoint output as an array rather than a single object, AireGlu will now accept it correctly.</p></div><h4 id="test-functionality-for-error-email-setup-glu-2259" tabindex="-1">Test Functionality for Error Email Setup (GLU-2259) <a class="header-anchor" href="#test-functionality-for-error-email-setup-glu-2259" aria-label="Permalink to “Test Functionality for Error Email Setup (GLU-2259)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>You can now test your error email configuration directly, to confirm error notifications are set up and delivering correctly, without needing to wait for a real error to trigger one.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>When setting up error email notifications, you can send a test email to confirm everything is configured correctly before relying on it.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="fixed-repository-linked-mcp-server-resolution-glu-3275" tabindex="-1">Fixed Repository-Linked MCP Server Resolution (GLU-3275) <a class="header-anchor" href="#fixed-repository-linked-mcp-server-resolution-glu-3275" aria-label="Permalink to “Fixed Repository-Linked MCP Server Resolution (GLU-3275)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Repository-linked MCP server configurations were only resolved against the standalone server configuration collection. As a result, a repo-linked server would appear correctly in the server list but return an error when opened directly, and fail with a &quot;server not found&quot; error when a connection or call was attempted against it. Lookups now also fall back to searching the linked repository&#39;s own server configurations, matching the behaviour already used when building the list view.</p></div><h4 id="fixed-body-editor-blocked-when-format-is-stream-glu-3279" tabindex="-1">Fixed Body Editor Blocked When Format Is Stream (GLU-3279) <a class="header-anchor" href="#fixed-body-editor-blocked-when-format-is-stream-glu-3279" aria-label="Permalink to “Fixed Body Editor Blocked When Format Is Stream (GLU-3279)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>When the HTTP Request task&#39;s Format was set to Stream, the body editor prevented the request content from being configured at all. This has been fixed so the body can be configured regardless of the selected format.</p></div>`,21)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};